Lemma flag_addr_range : forall fsb k pos, slot_ok k pos ->
  fsb + AFS_FLAGS <= flag_addr fsb k pos < fsb + AFS_HDR.
Proof.
  intros fsb k pos [Hk Hp]. pose proof (class_facts k Hk) as (A & B & _). unfold flag_addr, AFS_FLAGS, AFS_HDR in *. lia.
Qed.

