Lemma RFSI_init : forall fsb m,
  AIMG_TOP <= fsb -> fsb + AFS_SIZE <= aceil -> fsb mod 4096 = 0 -> aapp fsb AFS_SIZE ->
  rw_cells bsegs m ATP [C8 (wz fsb)] ->                                              (* [comment removed for export] *)
  (exists h0 h1 h2 h3 h4 h5 h6 h7 h8 h9 h10, rw_cells bsegs m fsb (hdr h0 h1 h2 h3 h4 h5 h6 h7 h8 h9 h10)) ->   (* [comment removed for export] *)
  (forall a, fsb + AFS_FLAGS <= a < fsb + AFS_HDR -> rw_cells bsegs m a [C1 (b8 0)]) ->  (* [comment removed for export] *)
  stk bsegs m (fsb + AFS_HDR) (fsb + AFS_SIZE) ->                                    (* [comment removed for export] *)
  stk bsegs m (sh fsb) (sh (fsb + AFS_SIZE)) ->                                     (* [comment removed for export] *)
  RFSI fsb [] m.
Proof.
  intros fsb m G1 G2 G3 G4 TLS HDR FL STF STS.
  split; [repeat split; assumption|]. split; [exact TLS|]. split; [exact HDR|].
  split; [intros f IN; destruct IN|]. split; [constructor|]. split; [| split; [exact STF| exact STS]].
  intros k pos S. unfold flagv. cbn. apply FL. exact (flag_addr_range fsb k pos S).
Qed.

(* [comment removed for export] *)
Lemma hdr_zero : forall m fsb,
  rw_cells bsegs m fsb (hdr (wz 0) (wz 0) (wz 0) (wz 0) (wz 0) (wz 0) (wz 0) (wz 0) (wz 0) (wz 0) (wz 0)) ->
  exists h0 h1 h2 h3 h4 h5 h6 h7 h8 h9 h10, rw_cells bsegs m fsb (hdr h0 h1 h2 h3 h4 h5 h6 h7 h8 h9 h10).
Proof. intros m fsb R. do 11 eexists. exact R. Qed.

